import { kSampleWindowBytes, warnLog } from "./logging.js";

/**
 * Manages video samples, providing functionalities for adding, finalizing,
 * and processing video data. It supports operations like time-based and
 * index-based sample selection, and provides chunks for decoding.
 */
export class SampleManager {
  /**
   * Calculates the timestamp of a sample in milliseconds.
   * @param {object} sample - The video sample.
   * @returns {number} - The sample's timestamp in milliseconds.
   */
  static sampleTimeMs(sample) {
    return (sample.cts * 1000) / sample.timescale;
  }

  /**
   * Creates an EncodedVideoChunk from a video sample.
   * @param {object} sample - The video sample.
   * @returns {EncodedVideoChunk} - The resulting video chunk.
   */
  static encodedVideoChunkFromSample(sample) {
    return new EncodedVideoChunk({
      type: sample.is_sync ? "key" : "delta",
      timestamp: (1e6 * sample.cts) / sample.timescale,
      duration: (1e6 * sample.duration) / sample.timescale,
      data: sample.data,
    });
  }

  /**
   * Initializes a new SampleManager instance.
   */
  constructor() {
    this.samples = [];
    this.originalSamples = null;
    this.currentIndex = 0;
    this.sliceStart = 0; // Absolute index of samples[0] within originalSamples
    this.windowBytes = kSampleWindowBytes; // Sliding window for on-demand loading
    this.finalized = false;
    this.state = "receiving"; // Initial state
    this.dataLoader = null; // Injected by the demuxer: loads sample data for a byte range
    this.pendingLoad = null; // In-flight data loading promise
    this.readyPromise = new Promise((resolve) => {
      this.resolveReadyPromise = resolve;
    });
  }

  /**
   * Sets the lightweight sample index (entries without data).
   * @param {Array<object>} entries - The index entries.
   */
  setIndex(entries) {
    this.samples = entries;
    this.originalSamples = entries;
  }

  /**
   * Injects the data loader used to fetch sample data on demand.
   * @param {function} loader - async (byteStart, byteEnd, firstSampleNumber, expectedCount) => void.
   *   The loader fills the `data` field of the index entries in
   *   [firstSampleNumber, firstSampleNumber + expectedCount) from the raw
   *   file bytes in [byteStart, byteEnd).
   */
  setDataLoader(loader) {
    this.dataLoader = loader;
  }

  /**
   * Ensures the sample data for the given index range (inclusive) is loaded.
   * Reads only the byte range covering the missing samples from the source file.
   * Concurrent/overlapping requests are serialized and merged.
   * @param {number} startIndex - The first sample index.
   * @param {number} endIndex - The last sample index (inclusive).
   * @returns {Promise<void>}
   */
  async ensureSampleData(startIndex, endIndex) {
    startIndex = Math.max(0, startIndex);
    endIndex = Math.min(endIndex, this.originalSamples.length - 1);

    // Wait for any in-flight load, then re-check what is still missing.
    while (this.pendingLoad) {
      await this.pendingLoad;
    }

    let first = -1;
    let last = -1;
    for (let i = startIndex; i <= endIndex; i++) {
      if (!this.originalSamples[i].data) {
        if (first < 0) first = i;
        last = i;
      }
    }
    if (first < 0) return; // Everything already loaded.

    // Byte range covering [first, last]; holes from interleaved audio are negligible.
    let minOffset = Infinity;
    let maxEnd = 0;
    for (let i = first; i <= last; i++) {
      const sample = this.originalSamples[i];
      if (sample.offset < minOffset) minOffset = sample.offset;
      if (sample.offset + sample.size > maxEnd)
        maxEnd = sample.offset + sample.size;
    }

    const loadPromise = this.dataLoader(
      minOffset,
      maxEnd,
      first,
      last - first + 1,
    );
    this.pendingLoad = loadPromise;
    try {
      await loadPromise;
    } finally {
      this.pendingLoad = null;
    }
  }

  /**
   * Finds the inclusive end index such that the byte size of samples in
   * [startIndex, endIndex] covers at least one sliding window. Operates on
   * this.samples (pre-finalize this is the full original index).
   * @param {number} startIndex - The first sample index.
   * @returns {number} - The inclusive end index.
   * @private
   */
  windowEndIndex(startIndex) {
    let bytes = 0;
    let end = startIndex;
    for (let i = startIndex; i < this.samples.length; i++) {
      bytes += this.samples[i].size;
      end = i;
      if (bytes >= this.windowBytes) break;
    }
    return end;
  }

  /**
   * Ensures data for the next `count` samples (from currentIndex) is loaded.
   * Only the samples needed right now are awaited; the rest of the sliding
   * window is filled by a background prefetch so the decoder never waits on
   * I/O. Data for samples already consumed (their bytes have been copied
   * into EncodedVideoChunks) is released, keeping compressed-data memory
   * bounded by the window size instead of the whole processing range.
   * @param {number} count - The number of upcoming samples that must be ready.
   * @returns {Promise<void>}
   */
  async ensureChunkData(count) {
    if (this.currentIndex >= this.samples.length) return;

    const absStart = this.sliceStart + this.currentIndex;
    const neededEnd =
      this.sliceStart +
      Math.min(this.currentIndex + count, this.samples.length) -
      1;

    // Wait only if the samples needed right now are not loaded yet.
    let firstMissing = -1;
    for (let i = absStart; i <= neededEnd; i++) {
      if (!this.originalSamples[i].data) {
        firstMissing = i;
        break;
      }
    }
    if (firstMissing >= 0) {
      await this.ensureSampleData(firstMissing, neededEnd);
    }

    // Release data for samples already handed to the decoder.
    for (let i = this.sliceStart; i < absStart; i++) {
      const entry = this.originalSamples[i];
      if (entry && entry.data) {
        entry.data = undefined;
      }
    }

    // Fill the rest of the sliding window in the background.
    const windowEnd = this.sliceStart + this.windowEndIndex(this.currentIndex);
    this.prefetch(absStart, windowEnd);
  }

  /**
   * Fills missing sample data in [startIndex, endIndex] (absolute indices)
   * in the background. ensureSampleData serializes overlapping loads via
   * pendingLoad, so this never runs more than one load at a time.
   * @param {number} startIndex - First absolute sample index.
   * @param {number} endIndex - Last absolute sample index (inclusive).
   * @private
   */
  prefetch(startIndex, endIndex) {
    let first = -1;
    for (let i = startIndex; i <= endIndex; i++) {
      if (!this.originalSamples[i].data) {
        first = i;
        break;
      }
    }
    if (first < 0) return;
    this.ensureSampleData(first, endIndex).catch((e) => {
      warnLog("SampleManager", "Prefetch failed", e);
    });
  }

  /**
   * Releases all loaded sample data, returning the memory to the GC.
   */
  releaseSampleData() {
    if (!this.originalSamples) return;
    for (const entry of this.originalSamples) {
      if (entry.data) {
        entry.data = undefined;
      }
    }
  }

  /**
   * Returns the total number of samples.
   * @returns {number} - The number of samples.
   */
  sampleCount() {
    return this.samples.length;
  }

  /**
   * Waits until the initial set of samples has been received and finalized.
   * @returns {Promise<void>}
   */
  async waitForReady() {
    if (this.state === "finalized") {
      return;
    }
    await this.readyPromise;
  }

  /**
   * Marks the sample index as ready, making the manager ready for processing.
   */
  finalize() {
    this.originalSamples = this.samples;
    this.resolveReadyPromise();
    this.resolveReadyPromise = null;
    this.state = "finalized";
  }

  /**
   * Finalizes the sample list to a specific time range, loading the sample
   * data for the required decode range (keyframe-based) on demand.
   * @param {number} timeRangeStart - The start time in milliseconds.
   * @param {number} timeRangeEnd - The end time in milliseconds.
   * @returns {Promise<[number, number, number]>} - The number of samples, and the actual start and end times.
   */
  async finalizeTimeRange(timeRangeStart, timeRangeEnd) {
    this.samples = this.originalSamples;
    let startIndex = 0;
    let endIndex = this.samples.length;
    let preciousStartIndex = 0;
    let preciousEndIndex = this.samples.length - 1;

    if (timeRangeStart !== undefined) {
      startIndex = this.lowerBound(timeRangeStart);
      preciousStartIndex = startIndex;
      // Rewind to the previous keyframe
      while (startIndex > 0 && !this.samples[startIndex].is_sync) {
        startIndex--;
      }
    }

    if (timeRangeEnd !== undefined) {
      endIndex = this.upperBound(timeRangeEnd);
      preciousEndIndex = endIndex;
      // Fast-forward to the next keyframe if the next sample is not a keyframe
      while (
        endIndex < this.samples.length - 1 &&
        !this.samples[endIndex + 1].is_sync
      ) {
        endIndex++;
      }
      endIndex++;
    }

    if (preciousEndIndex >= this.samples.length) {
      preciousEndIndex = this.samples.length - 1;
    }

    if (preciousStartIndex >= this.samples.length) {
      throw new Error("Invalid sample range");
    }

    const outputTimeRangeStart = SampleManager.sampleTimeMs(
      this.samples[preciousStartIndex],
    );
    const outputTimeRangeEnd = SampleManager.sampleTimeMs(
      this.samples[preciousEndIndex],
    );

    // Load only the first sliding window; the rest streams in via
    // ensureChunkData() as the decoder consumes samples.
    await this.ensureSampleData(startIndex, this.windowEndIndex(startIndex));

    this.sliceStart = startIndex;
    this.samples = this.samples.slice(startIndex, endIndex);
    this.currentIndex = 0;
    this.finalized = true;
    return [this.samples.length, outputTimeRangeStart, outputTimeRangeEnd];
  }

  /**
   * Finalizes the sample list to a specific index range, loading the sample
   * data for the required decode range (keyframe-based) on demand.
   * @param {number} startIndex - The starting sample index.
   * @param {number} endIndex - The ending sample index.
   * @returns {Promise<[number, number, number]>} - The number of samples, and the actual start and end times.
   */
  async finalizeSampleInIndex(startIndex, endIndex) {
    this.samples = this.originalSamples;
    let preciousStartIndex = startIndex;
    // Rewind to the previous keyframe
    while (startIndex > 0 && !this.samples[startIndex].is_sync) {
      startIndex--;
    }
    if (endIndex >= this.samples.length) {
      endIndex = this.samples.length - 1;
    }
    // Ensure the last sample has a valid timestamp
    while (endIndex > 0 && !this.samples[endIndex].cts) {
      endIndex--;
    }

    if (startIndex >= endIndex) {
      throw new Error("Invalid sample range");
    }

    const outputTimeRangeStart = SampleManager.sampleTimeMs(
      this.samples[preciousStartIndex],
    );
    const outputTimeRangeEnd = SampleManager.sampleTimeMs(
      this.samples[endIndex],
    );

    // Load only the first sliding window; the rest streams in via
    // ensureChunkData() as the decoder consumes samples.
    await this.ensureSampleData(startIndex, this.windowEndIndex(startIndex));

    this.sliceStart = startIndex;
    this.samples = this.samples.slice(startIndex, endIndex + 1);
    this.currentIndex = 0;
    this.finalized = true;
    return [this.samples.length, outputTimeRangeStart, outputTimeRangeEnd];
  }

  /**
   * Finds the first sample index at or after a given time.
   * @param {number} targetTime - The time in milliseconds.
   * @returns {number} - The sample index.
   */
  lowerBound(targetTime) {
    let left = 0;
    let right = this.samples.length - 1;

    while (left <= right) {
      const mid = Math.floor((left + right) / 2);
      const sampleTimeMs = SampleManager.sampleTimeMs(this.samples[mid]);

      if (sampleTimeMs < targetTime) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }

    return left;
  }

  /**
   * Finds the last sample index at or before a given time.
   * @param {number} targetTime - The time in milliseconds.
   * @returns {number} - The sample index.
   */
  upperBound(targetTime) {
    let left = 0;
    let right = this.samples.length - 1;

    while (left <= right) {
      const mid = Math.floor((left + right) / 2);
      const sampleTimeMs = SampleManager.sampleTimeMs(this.samples[mid]);

      if (sampleTimeMs <= targetTime) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }

    return right;
  }

  /**
   * Requests a number of chunks and provides them via a callback.
   * @param {number} count - The number of chunks to request.
   * @param {function} onChunk - Callback to handle each chunk.
   * @param {function} onExhausted - Callback when all samples are processed.
   * @returns {number} - The number of chunks processed.
   */
  requestChunks(count, onChunk, onExhausted) {
    let processed = 0;

    while (processed < count && this.currentIndex < this.samples.length) {
      const sample = this.samples[this.currentIndex];
      onChunk(SampleManager.encodedVideoChunkFromSample(sample));
      this.currentIndex++;
      processed++;
    }

    if (this.currentIndex >= this.samples.length) {
      onExhausted();
    }

    return processed;
  }

  /**
   * Finds a set of samples around a given percentage of the video for preview.
   * @param {number} percentage - The percentage (0-100) into the video.
   * @returns {Array<object>} - An array of samples for the preview.
   * @throws {Error} If called after the manager is finalized.
   */
  findSamplesAtPercentage(percentage) {
    if (this.finalized) {
      throw new Error("Cannot find sample in finalized SampleManager");
    }
    const sampleIndex = Math.floor(
      (percentage / 100) * (this.samples.length - 1),
    );

    // Rewind to the previous keyframe to ensure decodability
    let keyFrameIndex = sampleIndex;
    while (keyFrameIndex > 0 && !this.samples[keyFrameIndex].is_sync) {
      keyFrameIndex--;
    }
    return this.samples.slice(keyFrameIndex, sampleIndex + 1);
  }

  /**
   * Resets the manager to its initial state.
   */
  reset() {
    this.currentIndex = 0;
    this.sliceStart = 0;
    this.samples = [];
    this.originalSamples = null;
    this.currentIndex = 0;
    this.finalized = false;
  }

  /**
   * Resets the manager for reprocessing, keeping the original samples.
   */
  resetForReprocessing() {
    this.currentIndex = 0;
    this.sliceStart = 0;
    this.finalized = false;
    this.samples = this.originalSamples;
  }
}
